import{_ as a,o as i,c as s,ag as l}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"跨进程 DMA-BUF 的真正难点：所有权与回收合同","description":"SCM_RIGHTS 只能传递 fd，生产者与消费者仍需定义明确的 buffer 生命周期","frontmatter":{"title":"跨进程 DMA-BUF 的真正难点：所有权与回收合同","description":"SCM_RIGHTS 只能传递 fd，生产者与消费者仍需定义明确的 buffer 生命周期","tags":["DMA-BUF","SCM_RIGHTS","IPC","Buffer Ownership"],"date":"2026/07/17"},"headers":[],"relativePath":"linux/dmabuf-ownership-contract.md","filePath":"linux/dmabuf-ownership-contract.md","lastUpdated":1784519165000}'),t={name:"linux/dmabuf-ownership-contract.md"};function n(o,e,d,p,r,c){return i(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="跨进程-dma-buf-的真正难点-所有权与回收合同" tabindex="-1">跨进程 DMA-BUF 的真正难点：所有权与回收合同 <a class="header-anchor" href="#跨进程-dma-buf-的真正难点-所有权与回收合同" aria-label="Permalink to &quot;跨进程 DMA-BUF 的真正难点：所有权与回收合同&quot;">​</a></h1><p>DMA-BUF 让多个设备和进程共享同一块图像内存，Unix Socket 的 <code>SCM_RIGHTS</code> 又能把 fd 发送给另一个进程。很多实现做到这里就认为“零拷贝完成了”。</p><p>其实，fd 只是访问能力。更难的问题是：<strong>生产者什么时候可以再次写这块 buffer？</strong></p><h2 id="两种生命周期不能混淆" tabindex="-1">两种生命周期不能混淆 <a class="header-anchor" href="#两种生命周期不能混淆" aria-label="Permalink to &quot;两种生命周期不能混淆&quot;">​</a></h2><p>传递 fd 后，内核会让接收方获得自己的文件描述符引用，因此发送方关闭本地 fd，不会立刻销毁底层对象。这解决的是对象是否还存在。</p><p>但相机 buffer pool 往往会循环复用同一块内存：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame 100 写入 buffer A</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>fd(A) 发送给消费者</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>生产者把 A 放回采集队列</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>frame 104 再次写入 buffer A</span></span></code></pre></div><p>如果消费者此时才开始处理“frame 100”，它读到的可能已经是 frame 104。fd 仍然有效，数据语义却已经失效。</p><h2 id="一个最小-ownership-状态机" tabindex="-1">一个最小 ownership 状态机 <a class="header-anchor" href="#一个最小-ownership-状态机" aria-label="Permalink to &quot;一个最小 ownership 状态机&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FREE → CAPTURING → READY → LEASED → FREE</span></span></code></pre></div><ul><li><code>FREE</code>：可交给设备写入；</li><li><code>CAPTURING</code>：设备正在生产当前帧；</li><li><code>READY</code>：帧完成，等待分发；</li><li><code>LEASED</code>：一个或多个消费者仍在使用；</li><li>所有 lease 释放后才能回到 <code>FREE</code>。</li></ul><p>跨进程场景通常需要显式 ACK：生产者发送 <code>{sequence, fd, metadata}</code>，消费者完成后返回 <code>{sequence, done}</code>。只有匹配当前 generation 的 ACK 才能释放 lease。</p><h2 id="背压策略必须提前决定" tabindex="-1">背压策略必须提前决定 <a class="header-anchor" href="#背压策略必须提前决定" aria-label="Permalink to &quot;背压策略必须提前决定&quot;">​</a></h2><p>当消费者变慢时，系统只能在几种策略里选：</p><ol><li>阻塞生产者；</li><li>扩大 buffer pool；</li><li>丢弃最旧未消费帧；</li><li>断开慢消费者；</li><li>对不同消费者设置不同的 latest-only / every-frame 策略。</li></ol><p>没有策略并不代表没有背压，只是背压最终会表现成 queue 堆积、随机复用或内存增长。</p><h2 id="接收端必须验证真实-fd" tabindex="-1">接收端必须验证真实 fd <a class="header-anchor" href="#接收端必须验证真实-fd" aria-label="Permalink to &quot;接收端必须验证真实 fd&quot;">​</a></h2><p>packet 里的 <code>size</code> 只是发送方声明，不能证明 fd 对应对象真的足够大。mmap 前至少要检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>required = offset + stride × height</span></span>
<span class="line"><span>fd_capacity &gt;= required</span></span></code></pre></div><p>否则，metadata 与 fd 不匹配时可能直接触发 <code>SIGBUS</code>。同样，width、height、stride 的乘法要做 overflow 检查。</p><h2 id="unix-socket-路径也属于安全边界" tabindex="-1">Unix Socket 路径也属于安全边界 <a class="header-anchor" href="#unix-socket-路径也属于安全边界" aria-label="Permalink to &quot;Unix Socket 路径也属于安全边界&quot;">​</a></h2><p>服务启动时不要对可配置路径无条件 <code>unlink</code>。应先确认：</p><ul><li>路径位于受控目录；</li><li>现有对象确实是 socket；</li><li>owner 与权限符合预期；</li><li>bind 前后没有被替换；</li><li>socket 权限只允许需要的用户或组访问。</li></ul><h2 id="建议的协议字段" tabindex="-1">建议的协议字段 <a class="header-anchor" href="#建议的协议字段" aria-label="Permalink to &quot;建议的协议字段&quot;">​</a></h2><p>除几何信息外，建议每个消息至少包含：</p><ul><li>magic 与 version；</li><li>stream id；</li><li>sequence 与 generation；</li><li>timestamp 与 time domain；</li><li>plane count、offset、stride、size；</li><li>pixel format；</li><li>ACK policy 或 lease id。</li></ul><h2 id="如何验证不是-偶尔可用" tabindex="-1">如何验证不是“偶尔可用” <a class="header-anchor" href="#如何验证不是-偶尔可用" aria-label="Permalink to &quot;如何验证不是“偶尔可用”&quot;">​</a></h2><ul><li>人为让消费者 sleep，观察是否出现旧 sequence 对应新像素；</li><li>把 socket queue 压满，确认背压策略符合设计；</li><li>反复断开、重连消费者；</li><li>用错误 fd、短 fd、超大 stride 做负向测试；</li><li>在重启期间验证 generation，拒绝上一代 ACK；</li><li>长时间运行并监控 in-flight lease 数是否回落。</li></ul><p>零拷贝系统的完成线不是“没有 memcpy”，而是：<strong>每一块 buffer 在任何时刻都能回答谁拥有、谁在读、何时回收。</strong></p>`,29)])])}const f=a(t,[["render",n]]);export{u as __pageData,f as default};
